export function validateTaxRefundInputs(annualGrossIncome: number, lang: "en" | "es" = "en"): string | null {
  if (annualGrossIncome <= 0) return lang === "es" ? "El ingreso bruto anual debe ser mayor a cero." : "Annual gross income must be greater than zero.";
  return null;
}

const lang = (window as any).calcLang === "es" ? "es" : "en";
const estRefundLabel = (window as any).trfEstRefundLabel || "Estimated Refund";
const estOwedLabel = (window as any).trfEstOwedLabel || "Estimated Amount Owed";

let lastSummary = "";

edits.find:
  setSubtitle("refundOrOwedResult", result.isRefund ? "Estimated Refund" : "Estimated Amount Owed");

  lastSummary = `
